// Arma el JSON que recibe el controlador: consulta + fragmentos del manual + respuesta propuesta + citas.
const d = $input.first().json;
const entrada = JSON.stringify({
  consulta_original: d.mensaje,
  contexto_recuperado: d.contexto_recuperado,
  respuesta_propuesta: d.respuesta_agente,
  fuentes_citadas: d.fuentes_citadas,
  cita_valida_segun_sistema: d.cita_valida,
  respondio_no_se: d.respondio_no_se
}, null, 2);
return [{ json: { ...d, entrada_juez: entrada } }];

