{
  "type": "object",
  "properties": {
    "exactitud_factual": {
      "type": "integer",
      "minimum": 1,
      "maximum": 5,
      "description": "Puntaje de exactitud factual de 1 (inventa datos) a 5 (todo respaldado por el contexto)"
    },
    "estado_veredicto": {
      "type": "string",
      "enum": [
        "ACEPTADO",
        "CORREGIR",
        "RECHAZADO"
      ]
    },
    "cita_correcta": {
      "type": "boolean",
      "description": "Las fuentes citadas existen en el contexto recuperado"
    },
    "critica": {
      "type": "string",
      "description": "Qué debe corregir el asistente; 'Sin observaciones' si está aceptado"
    }
  },
  "required": [
    "exactitud_factual",
    "estado_veredicto",
    "cita_correcta",
    "critica"
  ],
  "additionalProperties": false
}

