// Aplica el umbral, el límite de reintentos y la verificación de citas. Calcula tokens y costo estimados.
const base = $('Armar_Entrada_Juez').first().json;
const j = $input.first().json.output || {};
const UMBRAL = 4;
const MAX_REINTENTOS = 2;

let exactitud = parseInt(j.exactitud_factual, 10);
if (isNaN(exactitud)) exactitud = 1;
let estado = String(j.estado_veredicto || '').toUpperCase();
if (!['ACEPTADO', 'CORREGIR', 'RECHAZADO'].includes(estado)) estado = 'RECHAZADO';
let critica = String(j.critica || '');
let citaOk = j.cita_correcta === true;

// Regla de código (no depende del juez): si no es un 'No sé' y las citas no coinciden con los metadatos, hay que corregir.
if (!base.respondio_no_se && !base.cita_valida) {
  exactitud = Math.min(exactitud, 3);
  if (estado === 'ACEPTADO') estado = 'CORREGIR';
    critica = (critica && critica !== 'Sin observaciones' ? critica + ' ' : '') + 'Citá el documento y la sección reales que figuran en los fragmentos recuperados.';
  citaOk = false;
}

let ruta;
if (estado === 'ACEPTADO' && exactitud >= UMBRAL) ruta = 'ACEPTAR';
else if (estado === 'RECHAZADO') ruta = 'ESCALAR';
else if (base.intentos < MAX_REINTENTOS) ruta = 'CORREGIR';
else ruta = 'ESCALAR';   // se agotaron los reintentos o no alcanzó el umbral: decide una persona

// Tokens estimados (aprox. 1 token cada 3,5 letras) y costo con precios públicos del modelo grande (USD por millón de tokens)
const t = s => Math.ceil(String(s || '').length / 3.5);
const P_IN = 0.15, P_OUT = 0.60;
const aIn = t(base.prompt_agente) + 519 + (t(base.prompt_agente) + 519 + t(base.contexto_recuperado));  // 2 llamadas: pedir fragmentos y responder
const aOut = t(base.respuesta_agente) + 60;
const jIn = t(base.entrada_juez) + 735, jOut = t(JSON.stringify(j)) + 10;
const costo = ((aIn + jIn) * P_IN + (aOut + jOut) * P_OUT) / 1e6;
const veredicto = { exactitud_factual: exactitud, estado_veredicto: estado, cita_correcta: citaOk, critica: critica };

return [{ json: {
  traceId: base.traceId,
  clave_auditoria: base.traceId + '-' + base.intentos,
  fecha: new Date().toISOString(),
  session_id: base.session_id,
  pregunta: base.mensaje,
  respuesta_agente: base.respuesta_agente,
  fuentes_citadas: (base.fuentes_citadas || []).join(' | '),
  cita_correcta: citaOk,
  exactitud_factual: exactitud,
  estado_veredicto: estado,
  critica: critica,
  intentos: base.intentos,
  ruta_final: ruta,
  tokens_entrada: aIn + jIn,
  tokens_salida: aOut + jOut,
  costo_usd: Number(costo.toFixed(6)),
  version_prompt: 'agente-rag-v1 | rubrica-juez-v3 | gpt-oss-120b',
  veredicto_json: JSON.stringify(veredicto)
} }];

// Devuelve al Manager solo lo necesario (el registro de auditoría ya quedó guardado).
const d = $('Aplicar_Reglas').first().json;
return [{ json: { status: 'ok', exactitud_factual: d.exactitud_factual, estado_veredicto: d.estado_veredicto,
  cita_correcta: d.cita_correcta, critica: d.critica, ruta_final: d.ruta_final,
  tokens_entrada: d.tokens_entrada, tokens_salida: d.tokens_salida, costo_usd: d.costo_usd, veredicto_json: d.veredicto_json } }];
